rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /c_resource_size/{file} {
      allow get: if resource.size == 1024 && resource.size is int;
    }
    match /c_resource_content_type/{file} {
      allow get: if resource.contentType == 'text/plain';
    }
    match /c_resource_metadata/{file} {
      allow get: if resource.metadata.owner == 'alice';
    }
    match /c_resource_metadata_missing/{file} {
      allow get: if resource.metadata.missing == 'x';
    }
    match /c_resource_metadata_get/{file} {
      allow get: if resource.metadata.get('missing', 'd') == 'd';
    }
    match /c_resource_name/{file} {
      allow get: if resource.name == 'dir/file.txt';
    }
    match /c_resource_bucket/{file} {
      allow get: if resource.bucket == 'demo-oracle.appspot.com';
    }
    match /c_resource_time_created_is_ts/{file} {
      allow get: if resource.timeCreated is timestamp;
    }
    match /c_resource_md5/{file} {
      allow get: if resource.md5Hash is string;
    }
    match /c_resource_missing_field/{file} {
      allow get: if resource.missing == 1;
    }
    match /c_resource_size_string/{file} {
      allow get: if resource.size == 1024;
    }
    match /c_resource_size_string_is_int/{file} {
      allow get: if resource.size is int;
    }
    match /c_resource_time_created_int/{file} {
      allow get: if resource.timeCreated < request.time;
    }
    match /c_resource_custom_field/{file} {
      allow get: if resource.whatever == 'x';
    }
    match /c_resource_null_on_get/{file} {
      allow get: if resource == null;
    }
    match /c_resource_absent_on_get/{file} {
      allow get: if resource == null;
    }
    match /c_request_resource_on_get/{file} {
      allow get: if request.resource == null;
    }
    match /c_request_path/{file} {
      allow get: if request.path == /b/demo-oracle.appspot.com/o/c_request_path/file.txt;
    }
    match /c_request_path_string/{file} {
      allow get: if request.path == '/b/demo-oracle.appspot.com/o/c_request_path_string/file.txt';
    }
    match /c_bucket_var/{file} {
      allow get: if bucket == 'demo-oracle.appspot.com';
    }
    match /c_auth_uid/{file} {
      allow get: if request.auth.uid == 'alice';
    }
    match /c_auth_claim_bool/{file} {
      allow get: if request.auth.token.admin == true;
    }
    match /c_auth_provider/{file} {
      allow get: if request.auth.token.firebase.sign_in_provider == 'password';
    }
    match /c_auth_null/{file} {
      allow get: if request.auth == null;
    }
    match /c_auth_absent/{file} {
      allow get: if request.auth == null;
    }
    match /c_time_set/{file} {
      allow get: if request.time == timestamp.date(2026, 1, 15) + duration.time(10, 20, 30, 123000000);
    }
    match /c_create_content_type/{file} {
      allow create: if request.resource.contentType.matches('image/.*');
    }
    match /c_create_metadata/{file} {
      allow create: if request.resource.metadata.k == 'v';
    }
    match /c_create_name/{file} {
      allow create: if request.resource.name == 'c_x/file.txt';
    }
    match /c_create_name_absent/{file} {
      allow create: if request.resource.bucket == 'x';
    }
    match /c_create_resource_null/{file} {
      allow create: if resource == null;
    }
    match /c_create_metadata_owner/{file} {
      allow create: if request.resource.metadata.owner == request.auth.uid;
    }
    match /c_create_size_float_cmp/{file} {
      allow create: if request.resource.size < 2.5 * 1024;
    }
    match /c_create_keys/{file} {
      allow create: if request.resource.keys().hasAll(['size', 'contentType']);
    }
    match /c_update_both/{file} {
      allow update: if request.resource.size > resource.size && request.resource.contentType == resource.contentType;
    }
    match /c_read_get/{file} {
      allow read: if true;
    }
    match /c_read_list/{file} {
      allow read: if true;
    }
    match /c_get_list/{file} {
      allow get: if true;
    }
    match /c_write_update/{file} {
      allow write: if true;
    }
    match /c_write_delete/{file} {
      allow write: if true;
    }
    match /c_method_list/{file} {
      allow list: if request.method == 'list';
    }
    match /c_fs_get/{file} {
      allow get: if firestore.get(/databases/(default)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }
    match /c_fs_exists/{file} {
      allow get: if firestore.exists(/databases/(default)/documents/users/$(request.auth.uid));
    }
    match /c_fs_get_unmocked/{file} {
      allow get: if firestore.get(/databases/(default)/documents/users/alice) == null;
    }
    match /c_fs_get_id/{file} {
      allow get: if firestore.get(/databases/(default)/documents/users/alice).id == 'alice';
    }
    match /c_fs_get_name/{file} {
      allow get: if firestore.get(/databases/(default)/documents/users/alice).__name__ == /databases/(default)/documents/users/alice;
    }
    match /c_fs_bare_get/{file} {
      allow get: if get(/databases/(default)/documents/users/alice).data.role == 'admin';
    }
    match /c_fs_lookups_2/{file} {
      allow get: if firestore.exists(/databases/(default)/documents/u/a) && firestore.exists(/databases/(default)/documents/u/b);
    }
    match /c_fs_lookups_3/{file} {
      allow get: if firestore.exists(/databases/(default)/documents/u/a) && firestore.exists(/databases/(default)/documents/u/b) && firestore.exists(/databases/(default)/documents/u/c);
    }
    match /c_fs_lookups_11/{file} {
      allow get: if firestore.exists(/databases/(default)/documents/u/d0) && firestore.exists(/databases/(default)/documents/u/d1) && firestore.exists(/databases/(default)/documents/u/d2) && firestore.exists(/databases/(default)/documents/u/d3) && firestore.exists(/databases/(default)/documents/u/d4) && firestore.exists(/databases/(default)/documents/u/d5) && firestore.exists(/databases/(default)/documents/u/d6) && firestore.exists(/databases/(default)/documents/u/d7) && firestore.exists(/databases/(default)/documents/u/d8) && firestore.exists(/databases/(default)/documents/u/d9) && firestore.exists(/databases/(default)/documents/u/d10);
    }
    match /c_err_or_true/{file} {
      allow get: if resource.missing == 1 || true;
    }
    match /c_err_and_false/{file} {
      allow get: if resource.missing == 1 && false;
    }
    match /c_not_err/{file} {
      allow get: if !(resource.missing == 1);
    }
    match /c_horses_or_true/{file} {
      allow get: if 'horses' || true;
    }
    match /c_div_zero/{file} {
      allow get: if 1 / 0 == 0;
    }
    match /c_int_overflow/{file} {
      allow get: if 9223372036854775807 + 1 < 0;
    }
    match /c_split/{file} {
      allow get: if resource.name.split('/') == ['dir', 'file.txt'];
    }
    match /c_size_emoji/{file} {
      allow get: if '😀'.size() == 2;
    }
    match /c_math_round/{file} {
      allow get: if math.round(-2.5) == -2;
    }
    match /c_list_neg_zero/{file} {
      allow get: if [0.0] == [-0.0];
    }
  }
}

rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /c_set_in_float/{file} {
      allow get: if 1 in [1.0].toSet();
    }
    match /c_hashing/{file} {
      allow get: if hashing.md5(b'abc').toBase64() == 'kAFQmDzST7DWlj99KOF/cg==';
    }
  }
}

rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /c_fs_database_var/{file} {
      allow get: if firestore.exists(/databases/$(database)/documents/users/alice);
    }
  }
}

rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /c_debug/{file} {
      allow get: if debug(true);
    }
  }
}
